(function(){"use strict";function toElementArray(target){if(!target)return[];if(typeof target==="string")return Array.from(document.querySelectorAll(target));if(target instanceof Element)return[target];if(target instanceof NodeList||Array.isArray(target)){return Array.from(target).filter(function(item){return item instanceof Element})}return[]}function wrapMenu(menu){var isAlreadyWrapped=menu.parentElement&&menu.parentElement.classList.contains("astroid-mobilemenu-inner")&&menu.parentElement.parentElement&&menu.parentElement.parentElement.classList.contains("astroid-mobilemenu-container");if(isAlreadyWrapped)return;var container=document.createElement("div");container.className="astroid-mobilemenu-container offcanvas-body p-0";var inner=document.createElement("div");inner.className="astroid-mobilemenu-inner";menu.parentNode.insertBefore(container,menu);container.appendChild(inner);inner.appendChild(menu)}function initMenu(menu){menu.querySelectorAll("li").forEach(function(li){li.classList.add("menu-item");li.querySelectorAll(":scope > ul").forEach(function(submenu){submenu.classList.add("dropdown-menus");submenu.querySelectorAll("li").forEach(function(submenuItem){submenuItem.classList.add("dropdown-menus-item")})})});wrapMenu(menu);menu.querySelectorAll("li").forEach(function(li){if(li.querySelector(":scope > ul")){li.classList.add("subMenu-wrapper")}});menu.querySelectorAll("li.subMenu-wrapper").forEach(function(li){if(li.querySelector(":scope > .menu-indicator"))return;var labelElement=li.querySelector(":scope > a, :scope > span");var submenu=li.querySelector(":scope > ul.dropdown-menus, :scope > ul");if(!labelElement||!submenu)return;var submenuLabel=labelElement.innerHTML;var indicator=document.createElement("span");indicator.className="menu-indicator";indicator.innerHTML='<i class="fas fa-angle-right"></i>';var indicatorBackItem=document.createElement("li");indicatorBackItem.className="menu-item menu-go-back";var indicatorBack=document.createElement("span");indicatorBack.className="menu-indicator-back d-flex align-items-center flex-wrap";indicatorBack.innerHTML='<i class="fas fa-angle-left"></i>'+submenuLabel;indicatorBackItem.appendChild(indicatorBack);labelElement.insertAdjacentElement("afterend",indicator);if(labelElement.tagName==="A"&&labelElement.classList.contains("item-link-heading")){labelElement.addEventListener("click",function(event){event.preventDefault();submenu.classList.toggle("menu_open")})}indicator.addEventListener("click",function(){submenu.classList.toggle("menu_open")});if(!submenu.querySelector(":scope > .menu-go-back")){submenu.insertAdjacentElement("afterbegin",indicatorBackItem)}indicatorBack.addEventListener("click",function(){submenu.classList.remove("menu_open")})})}function astroidMobileMenu(target){toElementArray(target).forEach(initMenu)}window.astroidMobileMenu=astroidMobileMenu})();